/* Pods echo accepted primary events and share the primary bank and bounded audio routing. */
#define OPTION_ECHO_CAP80 12
static int terrain_trace(int,int,int,int,int*);
static void emp_arc(int,int,int,int);
static int option_ready80(void){return g.mode==1&&!ex.intro&&!ex.travel&&!ex.victory&&!ex.refit&&ex.optionHeld80&&ex.optionsOn&&ex.options>0&&!ex.empDisable&&((!g.weaponHeat[g.weapon]&&g.weaponEnergy[g.weapon]>0)||ex.optionPaid80);}
/* Twelve dedicated echo slots preserve the original56 primary allocation slots. */
static Obj*option_shot80(void){for(int i=PRIMARY_SHOTS80;i<MAXS;i++)if(!g.shots[i].on){g.shots[i]=(Obj){.serial=++g.actorSerial,.on=1};return g.shots+i;}return 0;}
static void option_fire80(u32 marker){if(!option_ready80()||g.weapon==3||g.weapon==5||g.weapon==8)return;Obj source[16];int count=0;for(int i=0;i<PRIMARY_SHOTS80;i++){Obj*s=g.shots+i;if(s->on&&!s->echo80&&s->variant!=101&&s->serial>marker&&count<16)source[count++]=*s;}if(!count)return;int pods=clamp(ex.options,0,5);for(int n=0;n<pods;n++){int index=pods>1?n*(count-1)/(pods-1):count/2;Obj*s=option_shot80();if(!s)break;u32 serial=s->serial;*s=source[index];s->serial=serial;s->echo80=20;s->echoVariant80=g.variantEquip[g.weapon];s->sourceFamily=g.weapon+1;s->phase=-2;if(s->type==10){s->orbFull87=s->orbCharge87=clamp((s->orbFull87+4)/5,1,2);s->orbFade87=0;}s->x+=option_x(n)*Q-g.px;s->y+=option_y(n)*Q-player_y;s->previousX=s->x;s->previousY=s->y;}}

static int option_beam_width80(void){return clamp(beam_half_width()*45/100,1,10);}
static int option_beam_center80(int pod,int lane,int y){return option_x(pod)+lane*3+(option_y(pod)-7-y)*beam_slope(lane)/256;}
static void option_beam_refresh80(void){ex.optionBeam80=option_ready80()&&g.beam&&(g.weapon==3||g.weapon==5)&&!ex.phoenixTicks;for(int n=0;n<15;n++)ex.optionBeamTips80[n]=26;if(!ex.optionBeam80)return;for(int n=0;n<clamp(ex.options,0,5);n++)for(int lane=beam_split85()?-1:0;lane<=(beam_split85()?1:0);lane++){ex.optionBeamTips80[n*3+lane+1]=terrain_beam_front81(option_x(n)+lane*3,option_y(n)-7,beam_slope(lane),option_beam_width80(),26);}}
static int option_beam_point80(int pod,int x,int y,int radius){if(!option_ready80()||!ex.optionBeam80)return 0;for(int lane=beam_split85()?-1:0;lane<=(beam_split85()?1:0);lane++){float slope=beam_slope(lane)/256.0f;if(y<ex.optionBeamTips80[pod*3+lane+1]-radius||y>option_y(pod)-7+radius)continue;if(absn(x-option_beam_center80(pod,lane,y))<(radius+option_beam_width80())*sqrtf(1+slope*slope))return 1;}return 0;}
static int option_beam_count80(int x,int y,int radius){if(!ex.optionBeam80)return 0;int count=0;for(int n=0;n<clamp(ex.options,0,5);n++)count+=option_beam_point80(n,x,y,radius);return count;}
static int option_enemy_beam_count80(const Obj*o){if(!option_ready80()||!ex.optionBeam80)return 0;int count=0;for(int n=0;n<clamp(ex.options,0,5);n++){int hit=0;for(int lane=beam_split85()?-1:0;lane<=(beam_split85()?1:0);lane++){int side=pc_enemy_side_beam80(o,option_x(n)+lane*3,option_y(n)-7,beam_slope(lane),option_beam_width80(),ex.optionBeamTips80[n*3+lane+1]);if(side>=0){hit|=side;continue;}hit=option_beam_point80(n,o->x/Q,o->y/Q,o->type==4?32+o->power/24:13);if(hit)break;}count+=!!hit;}return count;}
static int option_emp_damage80(int damage,int x,int y){if(g.weapon!=8||!option_ready80())return damage;int count=0,range=110+power_level(8)*15;for(int n=0;n<clamp(ex.options,0,5);n++){int dx=option_x(n)-x,dy=option_y(n)-7-y;if(dx*dx+dy*dy>=range*range)continue;count++;if(ex.empCount<80){int i=ex.empCount;emp_arc(option_x(n)*Q,(option_y(n)-7)*Q,x*Q,y*Q);if(ex.empCount>i)ex.empArcs[i].variant=80;}}return damage+damage*count/5;}
